export default function collectTicketReads({messages,previousState,issues,pageInfo}){
 let state=previousState===null?{scan:0,count:0,after:null,cursors:[],hashes:[]}:JSON.parse(JSON.stringify(previousState));
 if(previousState!==null){if(!Array.isArray(issues)||issues.length>50||!pageInfo||typeof pageInfo.hasNextPage!=='boolean')throw new Error('Invalid Linear issue page.');
  for(const issue of issues){if(issue.description==null)continue;if(typeof issue.description!=='string')throw new Error('Linear description is not text.');const m=issue.description.match(/hash\:\s([\w#]+)/i);if(m&&!state.hashes.includes(m[1]))state.hashes.push(m[1]);}
  state.count+=issues.length;
  if(state.count>=50||!pageInfo.hasNextPage){state.scan++;state.count=0;state.after=null;state.cursors=[];}
  else{const cursor=pageInfo.endCursor;if(typeof cursor!=='string'||!cursor||state.cursors.includes(cursor))throw new Error('Linear pagination failed to advance.');state.after=cursor;state.cursors.push(cursor);}
 }
 const selected=state.scan===messages.length?messages.filter(m=>!state.hashes.includes(m.id)):[];
 return {state,more:state.scan<messages.length,after:state.after,selected};
}
